package com.bank.settle;

import java.util.logging.Logger;

// The settlement work expressed as a Runnable, so it can be RE-SUBMITTED
// to an executor as many times as needed — the correct reuse model.
class SettlementSweep implements Runnable {
    private static final Logger log = Logger.getLogger(SettlementSweep.class.getName());
    private final String runLabel;

    SettlementSweep(String runLabel) { this.runLabel = runLabel; }

    @Override public void run() {
        log.info(() -> "Settlement sweep [" + runLabel + "] running on thread "
                + Thread.currentThread().getName());
        // pretend to settle a batch of trades
        try { Thread.sleep(100); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        log.info(() -> "Settlement sweep [" + runLabel + "] completed.");
    }
}
