package com.bank.settle;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.*;

public class ThreadRestartDemo {
    private static final Logger log = Logger.getLogger(ThreadRestartDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        // 1) WRONG: start the SAME Thread twice -> IllegalThreadStateException.
        Thread sweepThread = new Thread(new SettlementSweep("raw-thread"), "sweep-1");
        log.info(() -> "Thread state before start: " + sweepThread.getState()); // NEW
        sweepThread.start();  // legal: NEW -> RUNNABLE
        sweepThread.join();   // wait for it to finish -> TERMINATED
        log.info(() -> "Thread state after finish: " + sweepThread.getState()); // TERMINATED

        try {
            sweepThread.start(); // ILLEGAL: no longer NEW
        } catch (IllegalThreadStateException e) {
            log.log(Level.SEVERE, "Second start() on the same Thread failed", e);
        }

        // 2) CORRECT: express work as a Runnable and submit to an executor pool.
        // The pool reuses worker threads; we can run the sweep as many times as needed.
        ExecutorService pool = Executors.newFixedThreadPool(2);
        for (int i = 1; i <= 3; i++) {
            final int n = i;
            pool.submit(new SettlementSweep("pool-run-" + n)); // re-run, no error
        }
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
        log.info(() -> "All pooled sweeps completed without any restart error.");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
